const __aivicBundle_16_sortImprovementProposalsByPriority = (() => {
  function sortImprovementProposalsByPriority(
    proposals: any[],
    sortOrder: 'asc' | 'desc' = 'asc'
  ): any[] {
    const sorted = [...proposals].sort((a, b) => {
      const priorityA = a.priority ?? a.priorityScore ?? 0;
      const priorityB = b.priority ?? b.priorityScore ?? 0;
  
      if (priorityA !== priorityB) {
        return sortOrder === 'asc' ? priorityA - priorityB : priorityB - priorityA;
      }
  
      const dateA = new Date(a.createdAt).getTime();
      const dateB = new Date(b.createdAt).getTime();
      return dateA - dateB;
    });
  
    return sorted;
  }
  return { sortImprovementProposalsByPriority };
})();
